@dataclass(repr=False)
class ZIPload(ResidentialEnduse):
    """
    Copyright (C) 2009 Battelle Memorial Institute
    @file ZIPloadload.cpp
    @addtogroup ZIPload
    @ingroup residential
    The ZIPload simulation is based on demand profile of the connected ZIPload loads.
    Individual power fractions and power factors are used.
    Heat fraction ratio is used to calculate the internal gain from ZIPload loads.
    The demand response model is based from a paper written by David Chassin and Jason Fuller
    "On the Equilibrium Dynamics of Demand Response in Thermostatic Loads" accepted by HICSS
    - This model is very much in the preliminary stage and only looks at the equilibrium solutions
    of a population of devices as a function of customer demand and thermostatic duty cycles
    @{

    Inherits from: residential_enduse

    Type: Instance (network topology element)

    Note: Inherits from residential_enduse (not in residential module)
    """
    _inherited_slots: ClassVar[list[str]] = []

    class_class_uri: ClassVar[URIRef] = GLM["ZIPload"]
    class_class_curie: ClassVar[str] = "glm:ZIPload"
    class_name: ClassVar[str] = "ZIPload"
    class_model_uri: ClassVar[URIRef] = GLM.ZIPload

    name: Union[str, ZIPloadName] = None
    heat_fraction: Optional[float] = None
    base_power: Optional[float] = None
    power_pf: Optional[float] = None
    current_pf: Optional[float] = None
    impedance_pf: Optional[float] = None
    is_240: Optional[Union[bool, Bool]] = None
    breaker_val: Optional[float] = None
    actual_power: Optional[Union[dict, Complex]] = None
    multiplier: Optional[float] = None
    heatgain_only: Optional[Union[bool, Bool]] = None
    demand_response_mode: Optional[Union[bool, Bool]] = None
    number_of_devices: Optional[int] = None
    thermostatic_control_range: Optional[int] = None
    number_of_devices_off: Optional[float] = None
    number_of_devices_on: Optional[float] = None
    rate_of_cooling: Optional[float] = None
    rate_of_heating: Optional[float] = None
    total_cycle_time: Optional[float] = None
